script:
frappe.ui.form.on('Sales Invoice', {
	refresh(frm) {
	    frm.add_custom_button(__('Copy Signing URL'), function() {
            frappe.call({
                method: 'frappe_signpad.api.get_signing_link',
                args: {
                    invoice_id: frm.doc.name,
                },
            }).then(e => {
                copyToClipboard(e.message);
                frappe.show_alert({
                    message: __('Copy Signing URL has been successfully copied to Clipboard!'),
                    indicator: 'green' // Can be 'green', 'yellow', 'red'
                }, 5); 
            });
        }, __("Actions"));
	}
});

async function copyToClipboard(text) {
  try {
    await navigator.clipboard.writeText(text);
    console.log('Text copied to clipboard successfully!');
  } catch (err) {
    console.error('Failed to copy text: ', err);
  }
}
